CREATE TEMPORARY VIEW user_exp_mapping_${grass_region_without_quote} AS
SELECT
    user_id
    ,exp_group_id
    ,experiment_id
FROM
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND is_assignment_log = 1
    AND is_search_whitelist = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW traffic_view_data_${grass_region_without_quote} AS
SELECT
    user_id
    ,page_type
    ,page_duration
FROM
    traffic.dwd_view_di__reg_live
WHERE
    grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND tz_type = 'local'
    AND user_id > 0   
    AND os IN ('ios', 'android')
    AND (
        (page_type = 'search' AND search_args.scenario_key IN ('PAGE_GLOBAL_SEARCH', 'PAGE_PDP_SEARCH', 'PAGE_PREFILL_SEARCH'))
        OR (page_type IN ('pre_search', 'search_suggest_page', 'image_search'))
        OR (page_type = 'product' AND (
            (pre_position_code like 'search.%' AND pre_property.search_args.scenario_key in ('PAGE_GLOBAL_SEARCH', 'PAGE_PDP_SEARCH', 'PAGE_PREFILL_SEARCH'))
            OR (pre_position_code like 'image_search.%')
            ))
    );

--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_group_metrics_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,page_type
    ,SUM(page_duration) / 3600000 AS duration
    ,COUNT(DISTINCT a.user_id) AS dau
FROM
    traffic_view_data_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2,3;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_page_level_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT 
    experiment_id
    ,exp_group_id
    ,page_type
    ,duration
    ,dau
FROM
    exp_group_metrics_${grass_region_without_quote};
